ALTER TABLE case_event_types ADD COLUMN description TEXT;

UPDATE case_event_types SET
  title = 'پرسش‌نامهٔ رفتار کودک — فرم معلم (SDQ)',
  description = 'بیست‌وپنج جملهٔ کوتاه دربارهٔ رفتار و حال دانش‌آموز در مدرسه — از احساسات و توجه تا دوستی‌ها و مهارت‌های اجتماعی. پاسخ درست یا غلط ندارد؛ هر جمله را با توجه به شش ماه گذشته علامت بزنید. حدود ۵ دقیقه وقت می‌برد.',
  fields = '[{"key":"i01","label":"به احساسات دیگران توجه و ملاحظه نشان می‌دهد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"pros"},{"key":"i02","label":"بی‌قرار و بیش‌فعال است و نمی‌تواند مدتی طولانی سر جایش بماند","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"hyper"},{"key":"i03","label":"اغلب از سردرد یا دل‌درد شاکی است","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"emo"},{"key":"i04","label":"آماده است وسایلش را با دیگران به اشتراک بگذارد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"pros"},{"key":"i05","label":"گاهی خشم شدید نشان می‌دهد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"cond"},{"key":"i06","label":"در کلاس و زنگ تفریح بیشتر تنها است","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"peer"},{"key":"i07","label":"معمولاً فرمان‌بر است و خواسته‌های بزرگ‌سالان را انجام می‌دهد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"cond","reverse":true},{"key":"i08","label":"نگرانی‌های فراوان دارد و اغلب نگران به نظر می‌رسد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"emo"},{"key":"i09","label":"اگر هم‌کلاسی‌ای ناراحت یا آسیب‌دیده باشد آماده کمک است","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"pros"},{"key":"i10","label":"پیوسته دست‌وپا می‌زند یا در جای خود می‌پیچد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"hyper"},{"key":"i11","label":"حداقل یک دوست خوب در کلاس دارد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"peer","reverse":true},{"key":"i12","label":"اغلب با دیگران دعوا یا درگیری می‌کند","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"cond"},{"key":"i13","label":"اغلب غمگین، دل‌شکسته یا بی‌حال است","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"emo"},{"key":"i14","label":"مورد پسند و پذیرفتهٔ هم‌کلاسی‌هایش است","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"peer","reverse":true},{"key":"i15","label":"به‌راحتی حواسش پرت می‌شود و تمرکزش را از دست می‌دهد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"hyper"},{"key":"i16","label":"در موقعیت‌های تازه مضطرب یا چسبنده است","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"emo"},{"key":"i17","label":"با کودکان کوچک‌تر مهربان و دلسوز است","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"pros"},{"key":"i18","label":"اغلب دروغ می‌گوید یا تقلب می‌کند","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"cond"},{"key":"i19","label":"از سوی هم‌سن‌ها اذیت یا مسخره می‌شود","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"peer"},{"key":"i20","label":"بی‌چشمداشت به دیگران کمک می‌کند","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"pros"},{"key":"i21","label":"پیش از عمل، فکر می‌کند و سنجیده رفتار می‌کند","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"hyper","reverse":true},{"key":"i22","label":"وسایل مدرسه یا دیگران را بدون اجازه برمی‌دارد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"cond"},{"key":"i23","label":"با بزرگ‌سالان بهتر از هم‌سن‌هایش کنار می‌آید","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"peer"},{"key":"i24","label":"ترس‌های فراوان و بی‌تناسب دارد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"emo"},{"key":"i25","label":"کارها را تا انتها دنبال می‌کند و دامنهٔ توجه خوبی دارد","type":"scale","scaleMax":2,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"],"required":true,"subscaleId":"hyper","reverse":true}]',
  bands = '[{"max":11,"label":"در محدودهٔ عادی","color":"ok","advice":"نمرهٔ کل دشواری‌ها عادی است — پایش دوره‌ای کافی است."},{"max":15,"label":"مرزی — نیاز به توجه","color":"warn","advice":"نمرهٔ کل مرزی است؛ بازپرسانی پس از ۴ تا ۶ هفته مداخله توصیه می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"نمرهٔ کل بالاست؛ به زیرمقیاس‌ها و ابزارهای اختصاصی همان حوزه بروید."}]',
  subscales = '[{"id":"emo","name":"حال و احساسات","bands":[{"max":4,"label":"در محدودهٔ عادی","color":"ok","advice":"نشانهٔ هیجانی برجسته نیست — پایش دوره‌ای کافی است."},{"max":5,"label":"مرزی — نیاز به توجه","color":"warn","advice":"نشانهٔ هیجانی مرزی است؛ پایش ماهانه و هماهنگی با خانواده توصیه می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"نشانهٔ هیجانی بالا است؛ ابزار اختصاصی اضطراب (SCARED) پیشنهاد می‌شود."}]},{"id":"cond","name":"رفتار و قاعده‌شکنی","bands":[{"max":2,"label":"در محدودهٔ عادی","color":"ok"},{"max":3,"label":"مرزی — نیاز به توجه","color":"warn","advice":"الگوی رفتاری مرزی؛ تقویت مثبت قواعد کلاس و هماهنگی خانه-مدرسه توصیه می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"قاعده‌شکنی بالاست؛ چک‌لیست ملاکی ODD و ارزیابی چندمرجعی پیشنهاد می‌شود."}]},{"id":"hyper","name":"توجه و بی‌قراری","bands":[{"max":5,"label":"در محدودهٔ عادی","color":"ok"},{"max":6,"label":"مرزی — نیاز به توجه","color":"warn","advice":"نشانه‌های توجه مرزی است؛ SNAP-IV معلم مکمل شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"نشانهٔ بالا؛ SNAP-IV والد و معلم برای ارزیابی چندمرجعی پیشنهاد می‌شود."}]},{"id":"peer","name":"دوستی‌ها و هم‌سالان","bands":[{"max":2,"label":"در محدودهٔ عادی","color":"ok"},{"max":3,"label":"مرزی — نیاز به توجه","color":"warn","advice":"روابط هم‌سالان مرزی؛ فعالیت گروهی ساخت‌یافته توصیه می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"مشکلات هم‌سالان بالا؛ چک‌لیست ملاکی اتیسم و ارزیابی مهارت اجتماعی پیشنهاد می‌شود."}]},{"id":"pros","name":"مهارت‌های اجتماعی (نقطهٔ قوت)","excludeFromTotal":true,"bands":[{"max":5,"label":"نیازمند تقویت — قابل توجه","color":"danger","advice":"مهارت‌های اجتماعی مطلوب پایین است؛ آموزش اجتماعی هدفمند لازم است."},{"max":7,"label":"مرزی","color":"warn"},{"max":10,"label":"در محدودهٔ مطلوب","color":"ok"}]}]',
  icon = '📋',
  updated_at = datetime('now')
WHERE key = 'ce-sdq-t-v1' AND deleted_at IS NULL;

UPDATE case_event_types SET
  title = 'چک‌لیست توجه و بی‌قراری — فرم خانواده (SNAP-IV)',
  description = 'بیست‌وشش جمله دربارهٔ توجه، بی‌قراری و تندی‌عصبانیت فرزندتان در خانه. برای هر جمله مشخص کنید رفتار چقدر شبیه اوست — پاسخ درست یا غلط ندارد. حدود ۱۰ دقیقه وقت می‌برد.',
  fields = '[{"key":"s01","label":"در جزئیات کارها بی‌دقت است و اشتباهات بی‌ملاحظه می‌کند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s02","label":"در حفظ توجه روی کارها یا بازی دشواری دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s03","label":"وقتی مستقیم با او حرف می‌زنند، به‌نظر نمی‌رسد گوش می‌دهد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s04","label":"دستورها را دنبال نمی‌کند و کارها را نیمه‌کاره می‌گذارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s05","label":"در مرتب‌کردن کارها و فعالیت‌هایش مشکل دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s06","label":"کارهایی که باید مدت زیادی فکر کند، برایش خسته‌کننده است و از آن فرار می‌کند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s07","label":"وسایل لازم برای کارها را گم می‌کند (مثلاً مداد، کتاب، اسباب‌بازی)","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s08","label":"با صدای اطراف به‌راحتی حواسش پرت می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s09","label":"در کارهای روزمره فراموش‌کار است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"ia"},{"key":"s10","label":"دست یا پایش را تکان می‌دهد یا در جای خود می‌پیچد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s11","label":"در کلاس یا موقعیت‌هایی که باید بنشیند، از جا بلند می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s12","label":"در موقعیت نامناسب می‌دود یا بالا می‌رود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s13","label":"در بازی یا فعالیت‌های آرام دچار دشواری است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s14","label":"انگار موتور روشنی دارد و همیشه در حرکت است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s15","label":"بیش از حد حرف می‌زند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s16","label":"پیش از تمام شدن سؤال، جوابش را برمی‌گرداند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s17","label":"نوبت‌گیری و منتظر ماندن برایش دشوار است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s18","label":"وسط حرف دیگران می‌پرد یا بازی آن‌ها را به‌هم می‌زند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"hi"},{"key":"s19","label":"از دست کسی می‌رود یا عصبانیت شدید نشان می‌دهد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s20","label":"با بزرگ‌سالان بحث و چانه‌زنی می‌کند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s21","label":"به خواسته‌ها و قواعد بزرگ‌سالان فعالانه «نه» می‌گوید","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s22","label":"آگاهانه دیگران را اذیت می‌کند","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s23","label":"اشتباه‌ها یا بدرفتاری خودش را گردن دیگران می‌اندازد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s24","label":"زودرنج و به‌راحتی عصبانی می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s25","label":"خشمگین و کینه‌توز است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s26","label":"وقتی از کسی دلخور می‌شود، دنبال تلافی برمی‌آید","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"}]',
  bands = NULL,
  subscales = '[{"id":"ia","name":"توجه و پیگیری کارها","bands":[{"max":16,"label":"در محدودهٔ عادی","color":"ok"},{"max":21,"label":"مرزی — نیاز به بررسی","color":"warn","advice":"نمرهٔ توجه مرزی است؛ فرم معلم را هم بگیرید و مقایسه کنید."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"کم‌توجهی بالاتر از برش والد گزارش شده؛ فرم معلم + ملاک‌های DSM لازم است."}]},{"id":"hi","name":"بی‌قراری و تندمزاجی","bands":[{"max":12,"label":"در محدودهٔ عادی","color":"ok"},{"max":16,"label":"مرزی — نیاز به بررسی","color":"warn"},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"بی‌قراری/تکانشگری بالاتر از برش والد؛ ارزیابی چندمرجعی پیشنهاد می‌شود."}]},{"id":"odd","name":"لجبازی و نافرمانی","bands":[{"max":11,"label":"در محدودهٔ عادی","color":"ok"},{"max":16,"label":"مرزی — نیاز به بررسی","color":"warn"},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"نافرمانی بالاست؛ چک‌لیست ملاکی ODD برای تفکیک از بی‌قراریِ تکانشی پیشنهاد می‌شود."}]}]',
  icon = '⚡',
  updated_at = datetime('now')
WHERE key = 'ce-snap-iv-p-v1' AND deleted_at IS NULL;

UPDATE case_event_types SET
  title = 'چک‌لیست توجه و بی‌قراری — فرم معلم (SNAP-IV)',
  description = 'بیست‌وشش جمله دربارهٔ توجه، بی‌قراری و تندی‌عصبانیت دانش‌آموز در کلاس. برای هر جمله مشخص کنید رفتار چقدر شبیه اوست — پاسخ درست یا غلط ندارد. حدود ۱۰ دقیقه وقت می‌برد.',
