odd"},{"key":"s23","label":"اشتباه‌ها یا بدرفتاری خودش را گردن دیگران می‌اندازد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s24","label":"زودرنج و به‌راحتی عصبانی می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s25","label":"خشمگین و کینه‌توز است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"},{"key":"s26","label":"وقتی از کسی دلخور می‌شود، دنبال تلافی برمی‌آید","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کمی","خیلی","خیلی زیاد"],"required":true,"subscaleId":"odd"}]',
