UPDATE case_event_types SET
  title = 'آزمون کوتاه حساب — ثبت درمانگر',
  description = 'دو دقیقه محاسبهٔ سریع + ده جفت مقایسهٔ عدد + جای‌گذاری روی خط عددی. نتیجه خودکار با انتظار پایه مقایسه می‌شود.',
