UPDATE case_event_types SET
  title = 'پرسش‌نامهٔ رفتار کودک — فرم خانواده (SDQ)',
  description = 'بیست‌وپنج جملهٔ کوتاه دربارهٔ رفتار و حال فرزندتان در خانه — از احساسات و توجه تا دوستی‌ها. پاسخ درست یا غلط ندارد؛ هر جمله را با توجه به شش ماه گذشته علامت بزنید. حدود ۵ دقیقه وقت می‌برد.',
  fields = '[{"key":"i01","label":"نسبت به دیگران مهربان و با ملاحظه است","type":"scale","scaleMax":2,"required":true,"subscaleId":"prosocial","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i02","label":"بی‌قرار و بیش‌فعال است و طولانی نمی‌تواند سر جایش بماند","type":"scale","scaleMax":2,"required":true,"subscaleId":"hyper","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i03","label":"اغلب سردرد یا دل‌درد دارد یا حالت عصبی نشان می‌دهد","type":"scale","scaleMax":2,"required":true,"subscaleId":"emotional","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i04","label":"با بزرگ‌سالان به‌خوبی حرف می‌زند و وسایلش را به اشتراک می‌گذارد","type":"scale","scaleMax":2,"required":true,"subscaleId":"prosocial","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i05","label":"گاهی عصبانیت یا خشم شدید نشان می‌دهد","type":"scale","scaleMax":2,"required":true,"subscaleId":"conduct","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i06","label":"در تنهایی می‌ماند و معمولاً تنها بازی می‌کند","type":"scale","scaleMax":2,"required":true,"subscaleId":"peer","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i07","label":"معمولاً اطاعت می‌کند و کارهایش را خوب انجام می‌دهد","type":"scale","scaleMax":2,"required":true,"subscaleId":"conduct","reverse":true,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i08","label":"نگرانی زیاد دارد و گاهی نگرانی‌اش او را ناتوان می‌کند","type":"scale","scaleMax":2,"required":true,"subscaleId":"emotional","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i09","label":"اگر کسی آسیب‌ببیند یا ناراحت باشد، دلش می‌خواهد کمکش کند","type":"scale","scaleMax":2,"required":true,"subscaleId":"prosocial","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i10","label":"پیوسته دست‌وپا می‌زند و آرام نمی‌نشیند","ty