"type":"scale","scaleMax":2,"required":true,"subscaleId":"prosocial","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i21","label":"پیش از فکر کردن کار می‌کند","type":"scale","scaleMax":2,"required":true,"subscaleId":"hyper","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i22","label":"کارهایی می‌کند که برای خودش یا دیگران دردسرساز است","type":"scale","scaleMax":2,"required":true,"subscaleId":"conduct","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i23","label":"با هم‌سالانش رابطهٔ خوبی دارد","type":"scale","scaleMax":2,"required":true,"subscaleId":"peer","reverse":true,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i24","label":"خوب تمرکز می‌کند و به‌راحتی از کارش منصرف نمی‌شود","type":"scale","scaleMax":2,"required":true,"subscaleId":"hyper","reverse":true,"scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]},{"key":"i25","label":"در رفتارش با بزرگ‌سالان مؤدب و مودب است","type":"scale","scaleMax":2,"required":true,"subscaleId":"prosocial","scaleLabels":["اصلاً درست نیست","تا حدی درست است","کاملاً درست است"]}]',
  subscales = '[{"id":"emotional","name":"هیجانی و اضطرابی","bands":[{"max":4,"label":"در محدودهٔ عادی","color":"ok","advice":"نشانهٔ هیجانی برجسته نیست — پایش دوره‌ای کافی است."},{"max":5,"label":"مرزی — نیاز به توجه","color":"warn","advice":"نشانه‌های اضطرابی-هیجانی مرزی است؛ پایش ماهانه و گفت‌وگو با خانواده توصیه می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"نشانه‌های هیجانی بالا است؛ ابزار اختصاصی اضطراب (SCARED) و ارزیابی بالینی پیشنهاد می‌شود."}]},{"id":"conduct","name":"رفتاری و قاعده‌شکنی","bands":[{"max":2,"label":"در محدودهٔ عادی","color":"ok"},{"max":3,"label":"مرزی — نیاز به توجه","color":"warn","advice":"الگوی رفتاری مرزی؛ تقویت مثبت قواعد و هماهنگی خانه-مرکز توصیه می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"الگوی قاعده‌شکنی بالا؛ ارزیابی تخصصی رفتار و آموزش والدگری لازم است."}]},{"id":"hyper","name":"بیش‌فعالی و کم‌توجهی","bands":[{"max":5,"label":"در محدودهٔ عادی","color":"ok"},{"max":7,"label":"مرزی — نیاز به توجه","color":"warn","advice":"نشانه‌های توجه/بی‌قراری مرزی است؛ فرم معلم و SNAP-IV مکمل شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"نشانه‌های بالا؛ ارزیابی چندمرجعی (والد + معلم) پیشنهاد می‌شود."}]},{"id":"peer","name":"مشکلات با هم‌سالان","bands":[{"max":2,"label":"در محدودهٔ عادی","color":"ok"},{"max":3,"label":"مرزی — نیاز به توجه","color":"warn","advice":"روابط هم‌سالان مرزی؛ فعالیت گروهی ساخت‌یافته توصیه می‌شود."},{"max":9999,"label":"قابل توجه — نیاز به بررسی بیشتر","color":"danger","advice":"مشکلات هم‌سالان بالا؛ ارزیابی مهارت‌های اجتماعی و مداخلهٔ گروهی لازم است."}]},{"id":"prosocial","name":"رفتار اجتماعی مطلوب (نقطهٔ قوت)","excludeFromTotal":true,"bands":[{"max":5,"label":"نیازمند تقویت — قابل توجه","color":"danger","advice":"مهارت‌های اجتماعی مطلوب پایین است؛ آموزش اجتماعی هدفمند و تمرین خانه توصیه می‌شود."},{"max":7,"label":"مرزی","color":"warn"},{"max":9999,"label":"در محدودهٔ مطلوب","color":"ok"}]